// More sounds for the deepmind-12d library. Same Preset shape as the ones in ../deepmind-12d.js (see CONTRACT.md → Preset).
// Several are in the style of records made on the DeepMind's ancestors, the Roland Juno-60 and Alpha Juno (see lineage/).

/** Select an envelope on the A D S R faders and set its four stage times. */
const ENV = (e, a, d, s, r) => ({ 'env.select': e, 'env.curves': false, [`${e}Env.attack`]: a, [`${e}Env.decay`]: d, [`${e}Env.sustain`]: s, [`${e}Env.release`]: r });
/** Open the FX page on one slot's first page of settings. */
const SLOT = (s) => ({ 'ui.page': 'fx', 'ui.fxSlot': String(s), 'ui.fxPart': 'a' });

