    phrase: { bpm: 110, loop: true, steps: [[0, 60, 0.4], [0.5, 64, 0.4], [1, 67, 0.4], [1.5, 72, 0.4], [2, 71, 0.4], [2.5, 67, 0.4], [3, 62, 0.4], [3.5, 65, 0.4], [4, 64, 0.4], [4.5, 60, 0.4], [5, 57, 0.4], [5.5, 60, 0.4], [6, 59, 0.9], [7, 55, 0.9]] },
